#!/usr/bin/env bash
set -euo pipefail

script_dir="$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd)"
assets_dir="$script_dir/assets"
archive_path="$(mktemp "${TMPDIR:-/tmp}/seminar14-assets.XXXXXX")"

cleanup() {
    rm -f "$archive_path"
}
trap cleanup EXIT

rm -rf "$assets_dir"
mkdir -p "$assets_dir"

decode_base64() {
    if base64 --help 2>&1 | grep -q -- '--decode'; then
        base64 --decode
    else
        base64 -D
    fi
}

decode_base64 > "$archive_path" <<'ASSETS_ARCHIVE'

ASSETS_ARCHIVE

expected_sha256="c895711d4ad4067e23d42c9392333a7d94805c777b6136377b5f5c84ce623db7"
if command -v sha256sum >/dev/null 2>&1; then
    actual_sha256="$(sha256sum "$archive_path" | cut -d ' ' -f 1)"
elif command -v shasum >/dev/null 2>&1; then
    actual_sha256="$(shasum -a 256 "$archive_path" | cut -d ' ' -f 1)"
else
    actual_sha256="$expected_sha256"
fi

if [[ "$actual_sha256" != "$expected_sha256" ]]; then
    echo "Ошибка: встроенный архив повреждён." >&2
    exit 1
fi

tar -xzf "$archive_path" -C "$assets_dir"

echo "Готово: данные созданы в $assets_dir"

